def _checked(ranges):
    """Return validated (start, end) tuples. Raises ValueError for start > end."""
    out = []
    for r in ranges:
        start, end = r
        if not (isinstance(start, int) and isinstance(end, int)):
            raise ValueError(f"range bounds must be int: {r!r}")
        if start > end:
            raise ValueError(f"range start is greater than end: {r!r}")
        out.append((start, end))
    return out


def merge(ranges):
    """Join overlapping and neighbouring closed integer ranges. See TASK.md."""
    items = sorted(_checked(ranges))
    result = []
    for start, end in items:
        if result and start <= result[-1][1] + 1:
            prev_start, prev_end = result[-1]
            result[-1] = (prev_start, max(prev_end, end))
        else:
            result.append((start, end))
    return result


def subtract(ranges, holes):
    """The integers in `ranges` that are not in `holes`, as merged ranges."""
    keep = merge(ranges)
    cut = merge(holes)
    result = []
    for start, end in keep:
        cur = start
        for h_start, h_end in cut:
            if h_end < cur or h_start > end:
                continue
            if h_start > cur:
                result.append((cur, h_start - 1))
            cur = h_end + 1
            if cur > end:
                break
        if cur <= end:
            result.append((cur, end))
    return merge(result)


def count(ranges):
    """How many distinct integers the ranges hold."""
    return sum(end - start + 1 for start, end in merge(ranges))
